// Flatten whatever the HTTP node returned into order records, then keep only
// well-formed ones. On an upstream failure (error item, empty object) nothing
// validates and we emit zero - the silent failure emerges here, not injected.
const input = $input.all();
const rows = [];
for (const it of input) {
  const b = it.json;
  if (Array.isArray(b)) { for (const r of b) rows.push(r); }
  else if (b && Array.isArray(b.data)) { for (const r of b.data) rows.push(r); }
  else if (b && b.id != null && b.title) { rows.push(b); }
}
const valid = rows.filter(r => r && r.id != null && typeof r.title === 'string' && r.title.length > 0);
return valid.map(r => ({ json: { orderId: r.id, customerId: r.userId, ref: r.title } }));
